import java.util.ArrayList;import java.util.List;class Solution {    private class Pair {        int value;        int index;        Pair(int value, int index) {            this.value = value;            this.index = index;        }    }    private int[] counts;    private Pair[] temp;    public List<Integer> countSmaller(int[] nums) {        int n = nums.length;        counts = new int[n];        Pair[] arr = new Pair[n];        for (int i = 0; i < n; i++) {            arr[i] = new Pair(nums[i], i);        }        temp = new Pair[n];        mergeSort(arr, 0, n - 1);        List<Integer> resultList = new ArrayList<>();        for (int count : counts) {            resultList.add(count);        }        return resultList;    }    private void mergeSort(Pair[] arr, int low, int high) {        if (low >= high) {            return;        }        int mid = low + (high - low) / 2;        mergeSort(arr, low, mid);        mergeSort(arr, mid + 1, high);        merge(arr, low, mid, high);    }    private void merge(Pair[] arr, int low, int mid, int high) {        for (int i = low; i <= high; i++) {            temp[i] = arr[i];        }        int p1 = low;        int p2 = mid + 1;        int current = low;        int rightCount = 0;        while (p1 <= mid && p2 <= high) {            if (temp[p1].value <= temp[p2].value) {                counts[temp[p1].index] += rightCount;                arr[current++] = temp[p1++];            } else {                arr[current++] = temp[p2++];                rightCount++;            }        }        while (p1 <= mid) {            counts[temp[p1].index] += rightCount;            arr[current++] = temp[p1++];        }        while (p2 <= high) {            arr[current++] = temp[p2++];        }    }}